"""Application sans état — lot 5 (UI Shiny, posture D-0007/D-0008).

L'application du MVP (stratégie §2.3/§4.6) : le syndic ouvre le dossier de
copropriété (ZIP, exemplaire maître D-0013), travaille, « Enregistrer »
télécharge une révision complète du dossier. Elle ne garde RIEN : ni
compte, ni secret, ni base de données — les données ne quittent jamais
le poste (D-0007). Le même code tourne en Shinylive (navigateur, livraison
principale D-0008 — export au lot suivant) et en repli serveur
(``shiny run app/``) : l'UI n'utilise pas le module ``js`` ; la sauvegarde
automatique passe par des messages custom Shiny + un script client
embarqué, identiques dans les deux modes.

Architecture (plan lot 5 §C) : ce module ne fait que lier Shiny — toute
la logique vit dans les modules purs ``pdf_appel.py`` (PDF fidèle ODS)
et ``revision.py`` (périodes, saisies journalisées, émission, envois,
révision du dossier), consommés avec ``core/`` (lot 3) et ``dossier/``
(lot 4) sans réouverture (seule extension approuvée : fix F, D-0035).

Assistant 5 étapes calqué sur l'ODS : période → factures → relevés d'eau
→ contrôle (récapitulatif FACTURES, sommes vérifiées) → émission (7 PDF
+ ZIP + envois semi-manuels D-0001). Sauvegarde automatique : la copie de
travail = la révision complète du dossier, stockée côté client
(IndexedDB, plan §E) ; alerte avant fermeture sans enregistrement.
"""
# This file is part of loftRv2 — lot 5 (application sans état).

import base64
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

ICI = Path(__file__).resolve().parent
RACINE = ICI.parent
for _chemin in (str(RACINE), str(ICI)):
    if _chemin not in sys.path:  # pragma: no cover - amorçage shiny run
        sys.path.insert(0, _chemin)

from shiny import App, reactive, render, ui  # noqa: E402

import core  # noqa: E402 — noyau lot 3
import export_csv  # noqa: E402 — lot 12 (CSV)
import pdf_appel  # noqa: E402
import revision  # noqa: E402

VERSION_APPLICATION = "lot 12"
"""Version affichée (onglet Intégrité) : après un redéploiement, l'opérateur
vérifie qu'il n'est pas resté sur une version en cache du navigateur."""

# ---------------------------------------------------------------------------
# Constantes d'affichage (aucune donnée réelle, D-0002) et aide contextuelle
# ---------------------------------------------------------------------------

TYPES_CHARGE = [t.value for t in core.TypeCharge]
MODES = [m.value for m in core.ModeRepartition]
MODE_DEFAUT = "Règle par défaut du type de charge"
MOTIFS_CREDIT = [m.value for m in core.MotifCredit]
MOYENS = [m.value for m in core.MoyenPaiement]
LOTS = ["F1", "F2", "F3", "F4", "F5", "F6", "F7"]

# Aide contextuelle (lot 7, ergonomie) : « quoi saisir, pourquoi, quoi
# faire en cas de doute » — survol des champs et des étapes. Aucune
# référence interne (revue des libellés) ; le dictionnaire est exposé
# pour les tests de régression (tests/test_libelles.py).
AIDES = {
    "initiales":
        "Vos initiales (2 à 4 lettres majuscules) identifient chaque "
        "action dans le journal du dossier. Elles sont demandées une fois "
        "par session, au premier geste.",
    "enregistrer":
        "Télécharge une révision complète du dossier (fichier ZIP). CE "
        "fichier devient l'exemplaire maître : ouvrez-le à la session "
        "suivante et conservez une copie ailleurs (clé USB, disque). En "
        "cas de doute : enregistrez, cela ne coûte rien.",
    "dossier_zip":
        "Le dossier de copropriété est le fichier ZIP qui contient tout : "
        "annuaire des lots, historique, justificatifs. Il reste sur votre "
        "poste — rien n'est envoyé ailleurs. En cas d'erreur, le dossier "
        "est refusé et rien n'est retenu.",
    "etape1":
        "Un appel de fonds par semestre (ex. 2026-S2). Ouvrez la période "
        "à reprendre, ou créez celle du semestre en cours : tout le reste "
        "de l'assistant travaille sur la période ouverte ici.",
    "etape2":
        "Saisissez ici chaque facture reçue du semestre. La date est "
        "obligatoire ; une date hors semestre est acceptée et signalée. "
        "Pour corriger une facture déjà saisie : choisissez-la dans "
        "« Facture à corriger », le formulaire se recharge, modifiez "
        "puis cliquez « Corriger la facture ».",
    "fact_fournisseur":
        "Nom du fournisseur si connu (facultatif) — il apparaît dans le "
        "libellé de la facture.",
    "fact_type":
        "La nature de la charge détermine la règle de répartition "
        "(ex. l'eau est répartie à la consommation relevée). En cas de "
        "doute, reprenez le libellé de la facture papier.",
    "fact_montant":
        "Montant total de la facture en euros — virgule ou point acceptés "
        "(ex. 1234,56).",
    "fact_mode":
        "La règle par défaut suffit dans le cas usuel. Choisir une autre "
        "règle est une exception : elle reste tracée au journal.",
    "fact_date":
        "Date de la facture (année-mois-jour), obligatoire. Une date hors "
