        "au journal.",
    "copropriete":
        "Ces informations (nom, adresse, contact du syndic) apparaissent "
        "en tête des PDF. Remplissez-les une fois à l'adoption ; en cas "
        "de doute, laissez vide — les PDF restent corrects sans elles.",
    "encaissement":
        "Notez chaque paiement reçu, par lot et par semestre : date, "
        "montant, moyen, référence. Le tableau de rapprochement se met "
        "à jour tout seul.",
    "credit":
        "Une somme à déduire du solde d'un lot (excédent, "
        "régularisation, acompte…) : montant positif et motif "
        "obligatoire. Le solde à payer diminue d'autant.",
    "figage":
        "Verrou définitif d'une période soldée et archivée : plus rien "
        "ne pourra y être saisi, jamais. À n'utiliser qu'une fois le "
        "suivi terminé — en cas de doute, ne verrouillez pas.",
    "export":
        "Deux fichiers CSV (factures, soldes) qui s'ouvrent dans "
        "LibreOffice Calc ou Excel : c'est la porte de sortie du dossier "
        "si le classeur ODS est un jour abandonné. Ils contiennent toutes "
        "les périodes et ne quittent pas votre poste.",
}

DEBOUNCE_SAUVEGARDE = 5.0
"""Débounce de la sauvegarde automatique (secondes, plan §E)."""

STYLES = """
.badge { display:inline-block; padding:2px 8px; border-radius:10px;
         font-size:0.85em; font-weight:600; }
.b-brouillon { background:#fff3cd; color:#664d03; }
.b-emis { background:#d1e7dd; color:#0f5132; }
.b-fige { background:#e2e3e5; color:#41464b; }
.b-ok { background:#d1e7dd; color:#0f5132; }
.b-err { background:#f8d7da; color:#842029; }
table.loft { border-collapse:collapse; margin:0.4em 0; font-size:0.9em; }
table.loft th, table.loft td { border:1px solid #ccc; padding:3px 7px;
                               text-align:right; }
table.loft td.lib, table.loft th.lib { text-align:left; }
"""

# Script client : sauvegarde automatique (IndexedDB, plan §E — le dossier
# réel dépasse le quota localStorage, plan §B) + alerte avant fermeture.
# Fonctionne à l'identique en Shinylive (iframe same-origin) et en repli
# serveur — messages custom Shiny dans les deux modes.
SCRIPT_CLIENT = r"""
(function () {
  const NOM_BASE = "loftRv2-travail", MAGASIN = "copies";
  const CLE_VERROU = "loftRv2-ecriture";
  let base = null, alerteArmee = false, nonce = 0;
  let cleCourante = null, libelleCourant = null, lectureSeule = null;

  function ouvrir() {
    return new Promise((res, rej) => {
      const r = indexedDB.open(NOM_BASE, 1);
      r.onupgradeneeded = () => r.result.createObjectStore(MAGASIN);
      r.onsuccess = () => res(r.result);
      r.onerror = () => rej(r.error);
    });
  }
  function magasiner(mode, cle, valeur) {
    return new Promise(async (res, rej) => {
      try {
        const d = base || (base = await ouvrir());
        const t = d.transaction(MAGASIN, mode).objectStore(MAGASIN);
        const q = valeur !== undefined ? t.put(valeur, cle) : t.get(cle);
        q.onsuccess = () => res(q.result);
        q.onerror = () => rej(q.error);
      } catch (e) { rej(e); }
    });
  }
  function supprimer(cle) {
    return new Promise(async (res, rej) => {
      try {
        const d = base || (base = await ouvrir());
        const q = d.transaction(MAGASIN, "readwrite")
          .objectStore(MAGASIN).delete(cle);
        q.onsuccess = () => res(true);
        q.onerror = () => rej(q.error);
      } catch (e) { rej(e); }
    });
  }
  function cles() {
    return new Promise(async (res, rej) => {
      try {
        const d = base || (base = await ouvrir());
        const q = d.transaction(MAGASIN, "readonly")
          .objectStore(MAGASIN).getAllKeys();
        q.onsuccess = () => res(q.result || []);
        q.onerror = () => rej(q.error);
      } catch (e) { rej(e); }
    });
  }
  async function lister() {
    const sortie = [];
    for (const cle of await cles()) {
      const v = await magasiner("readonly", cle);
      if (!v) continue;
      sortie.push({ cle: cle, horodatage: v.horodatage || "",
                    libelle: v.libelle || "",
                    ancienne: cle === "travail" });
    }
    sortie.sort((a, b) => (b.horodatage || "").localeCompare(
      a.horodatage || ""));
    Shiny.setInputValue("copies_travail", { n: ++nonce, copies: sortie });
  }
  function avertir(e) { e.preventDefault(); e.returnValue = ""; }
  function armer(b) {
    if (b && !alerteArmee) window.addEventListener("beforeunload", avertir);
    if (!b && alerteArmee)
      window.removeEventListener("beforeunload", avertir);
    alerteArmee = b;
    window.__loftAlerteArmee = b;
  }
  Shiny.addCustomMessageHandler("loft-copie", async (m) => {
    try {
      if (m.action === "identite") {
        cleCourante = m.cle || null;
        libelleCourant = m.libelle || null;
        await lister();
      } else if (m.action === "ecrire") {
        const cle = m.cle || cleCourante;
        if (!cle) return;
        await magasiner("readwrite", cle,
          { horodatage: m.horodatage, b64: m.b64,
            libelle: m.libelle || libelleCourant || "" });
        await lister();
        Shiny.setInputValue("loft_stockage_ok", true);
      } else if (m.action === "effacer") {
        if (m.cle) await supprimer(m.cle);
        await lister();
      } else if (m.action === "effacer_tout") {
        for (const cle of await cles()) await supprimer(cle);
        await lister();
      } else if (m.action === "lire") {
        const cle = m.cle || cleCourante;
        const v = cle ? await magasiner("readonly", cle) : null;
        Shiny.setInputValue("copie_travail_contenu",
          { b64: v ? v.b64 : null, cle: cle, n: ++nonce });
      } else if (m.action === "reessayer_verrou") {
        await demanderVerrou();
      }
    } catch (e) { Shiny.setInputValue("loft_stockage_ok", false); }
  });
  Shiny.addCustomMessageHandler("loft-alerte", (m) => {
    if (lectureSeule) return;   // un onglet en lecture seule n'a rien à perdre
    armer(!!m.armee);
  });
  // -- verrou d'onglet (Q-G) : un seul écrivain par origine --------------
  // ``lectureSeule`` est publié seulement une fois la session Shiny
  // connectée : un setInputValue émis avant l'ouverture du websocket
  // serait perdu (constaté en navigateur — le second onglet restait
  // écrivain). Le verrou, lui, est demandé immédiatement.
  function publierEtat() {
    if (lectureSeule === null) return;
    try { Shiny.setInputValue("loft_onglet_secondaire", lectureSeule); }
    catch (e) { /* session pas encore prête : republication plus tard */ }
  }
  async function demanderVerrou() {
    if (!navigator.locks) {
      lectureSeule = false;
      try { Shiny.setInputValue("loft_verrou_indisponible", true); }
      catch (e) { /* republication plus tard */ }
      return;
    }
    await navigator.locks.request(CLE_VERROU,
      { mode: "exclusive", ifAvailable: true }, async (verrou) => {
        if (!verrou) {
          lectureSeule = true;
          armer(false);
          publierEtat();
          return;
        }
        lectureSeule = false;
        publierEtat();
        await new Promise(() => {});  // tient le verrou jusqu'à la fermeture
      });
  }
  function connecte() {
    try {
      return !!(window.Shiny && Shiny.shinyapp && Shiny.shinyapp.$socket
                && Shiny.shinyapp.$socket.readyState === 1);
    } catch (e) { return false; }
  }
  function demarrerQuandConnecte() {
    try {
      Shiny.setInputValue("loft_verrou_indisponible", !navigator.locks);
      publierEtat();
      lister();
    } catch (e) { /* l'état sera republié au prochain essai */ }
  }
  document.addEventListener("shiny:connected", demarrerQuandConnecte);
  let essaisConnexion = 0;
  const attente = setInterval(() => {
    essaisConnexion++;
    if (connecte()) {
      demarrerQuandConnecte();
      clearInterval(attente);
    } else if (essaisConnexion > 300) {  // 60 s
      clearInterval(attente);
    }
  }, 200);
  demanderVerrou();
})();
"""


def badge(etat: str) -> str:
    return f'<span class="badge b-{etat}">{etat}</span>'


def _rappel(message: str) -> ui.Tag:
    return ui.p({"style": "color:#888;"}, message)


def _aide(cle: str) -> ui.Tag:
    """Infobulle d'aide contextuelle (survol) — texte de ``AIDES[cle]``."""
    return ui.tooltip(
        ui.span("?", style=(
            "display:inline-block; width:1.15em; height:1.15em; "
            "line-height:1.15em; text-align:center; border-radius:50%; "
            "background:#0d6efd; color:#fff; font-size:0.72em; "
            "font-weight:700; cursor:help; margin-left:0.35em; "
            "vertical-align:middle;")),
        AIDES[cle], placement="auto")


def _champ(entree, cle: str) -> ui.Tag:
    """Un champ de saisie avec son aide contextuelle (survol du champ)."""
    return ui.tooltip(entree, AIDES[cle], placement="auto")


# ---------------------------------------------------------------------------
# Interface
# ---------------------------------------------------------------------------


def _etape(titre: str, *contenus) -> ui.Tag:
    """Une étape de l'assistant : titre + aide contextuelle « ? ».

    ``contenus`` peut commencer par une chaîne : la clé de l'aide
    contextuelle (``AIDES``) — le « ? » apparaît alors à côté du titre.
    """
    if contenus and isinstance(contenus[0], str):
        entete = ui.card_header(
            {"style": "display:flex; align-items:center; gap:0.2em;"},
            titre, _aide(contenus[0]))
        contenus = contenus[1:]
    else:
        entete = ui.card_header(titre)
    return ui.card(entete, *contenus)


app_ui = ui.page_fluid(
    ui.tags.head(ui.tags.style(STYLES)),
    ui.tags.header(
        {"style": "display:flex; flex-wrap:wrap; gap:1em; align-items:end; "
                  "padding:0.6em 0;"},
        ui.h3({"style": "margin:0;"}, "Appel de fonds — copropriété"),
        _champ(ui.input_text("initiales", "Vos initiales", value="",
                             width="110px", placeholder="AB"),
               "initiales"),
        ui.div({"style": "flex:1;"}, ui.output_ui("temoin_sauvegarde")),
        ui.output_ui("bouton_enregistrer"),
    ),
    ui.card(
        _champ(ui.input_file(
            "dossier_zip", "Ouvrir le dossier de copropriété (fichier "
            "ZIP) :", accept=".zip", button_label="Choisir le dossier…"),
            "dossier_zip"),
        ui.output_ui("etat_dossier"),
        ui.output_ui("banniere_onglet"),
        ui.output_ui("banniere_copie"),
        ui.layout_columns(
            ui.input_select("copie_choisie", "Copie de travail",
                            choices={}),
            ui.input_action_button("reprendre_copie",
                                   "Reprendre la copie"),
            ui.input_action_button("jeter_copie", "Jeter la copie"),
            ui.input_action_button("jeter_toutes",
                                   "Jeter toutes les copies"),
            col_widths=(5, 3, 2, 2)),
    ),
    ui.navset_tab(
        ui.nav_panel(
            "Assistant",
            _etape(
                "Étape 1 — Période", "etape1",
                ui.output_ui("liste_periodes"),
                ui.layout_columns(
                    ui.input_select("periode_choisie", "Ouvrir une période",
                                    choices=[]),
                    ui.input_action_button("ouvrir_periode",
                                           "Ouvrir la période"),
                    col_widths=(8, 4),
                ),
                ui.layout_columns(
                    # B-20 (D-0043) : aucun exercice proposé par défaut —
                    # un clic sans retouche ne crée plus 2100-S1 pour
                    # toujours ; la saisie est obligatoire (garde dans
                    # _creer).
                    ui.input_numeric("exercice", "Exercice", value=None),
                    ui.input_select("semestre", "Semestre",
                                    choices={"1": "S1", "2": "S2"}),
                    ui.input_action_button("creer_periode",
                                           "Créer la période"),
                    col_widths=(4, 4, 4),
                ),
                ui.output_ui("periode_courante"),
            ),
            _etape(
                "Étape 2 — Factures", "etape2",
                ui.output_ui("periode_active_rappel"),
                ui.layout_columns(
                    _champ(ui.input_text("fact_fournisseur", "Fournisseur"),
                           "fact_fournisseur"),
                    _champ(ui.input_select("fact_type", "Type de charge",
                                           choices=TYPES_CHARGE),
                           "fact_type"),
                    ui.input_text("fact_detail", "Détail"),
                    col_widths=(4, 8),
                ),
                ui.layout_columns(
                    _champ(ui.input_text("fact_montant", "Montant (€)",
                                         placeholder="1234,56"),
                           "fact_montant"),
                    _champ(ui.input_select("fact_mode", "Mode de répartition",
                                           choices=[MODE_DEFAUT] + MODES),
                           "fact_mode"),
                    _champ(ui.input_text("fact_date",
                                         "Date de la facture (obligatoire)",
                                         placeholder="2100-03-15"),
                           "fact_date"),
                    col_widths=(4, 4, 4),
                ),
                ui.input_action_button("ajouter_facture",
                                       "Ajouter la facture"),
                ui.output_ui("table_factures"),
                ui.output_ui("zone_correction_facture"),
            ),
            _etape(
                "Étape 3 — Relevés d'eau", "etape3",
                ui.layout_columns(
                    ui.input_text("date_releve",
                                  "Date du relevé (obligatoire)",
                                  placeholder="2100-06-30"),
                    ui.input_action_button("enregistrer_date_releve",
                                           "Enregistrer la date"),
                    col_widths=(8, 4),
                ),
                ui.output_ui("date_releve_affichage"),
                # lignes statiques (jamais re-rendues : la saisie en cours
                # survit aux mises à jour de l'interface — sauvegarde auto
                # comprise) ; le statut de chaque lot vit à part.
                *[
                    ui.layout_columns(
                        ui.div(ui.strong(lot),
                               ui.output_ui(f"releve_statut_{lot}")),
                        ui.input_text(f"compteur_{lot}", "Compteur",
                                      width="110px"),
                        ui.input_text(f"ancien_{lot}", "Ancien index",
                                      width="110px"),
                        ui.input_text(f"nouvel_{lot}", "Nouvel index",
                                      width="110px"),
                        _champ(ui.input_checkbox(f"remplacement_{lot}",
                                                 "Compteur remplacé"),
                               "remplacement"),
                        ui.input_action_button(f"releve_{lot}",
                                               "Enregistrer"),
                        col_widths=(2, 2, 2, 2, 2, 2),
                    )
                    for lot in LOTS
                ],
            ),
            _etape(
                "Étape 4 — Contrôle", "etape4",
                ui.output_ui("controle"),
            ),
            _etape(
                "Étape 5 — Émission", "etape5",
                ui.output_ui("periode_active_rappel2"),
                ui.input_action_button("emettre", "Émettre l'appel"),
                ui.output_ui("emission"),
                ui.p("Après émission, téléchargez la révision complète du "
                     "dossier avec « Enregistrer » (en haut de la page) — "
                     "c'est ce ZIP qui devient l'exemplaire maître du "
                     "dossier."),
            ),
        ),
        ui.nav_panel(
            "Annuaire & copropriété",
            _etape("Annuaire des lots (F1, F2, …)",
                   ui.output_ui("annuaire")),
            _etape(
                "Changement de famille", "changer_famille",
                ui.input_select("famille_lot", "Lot", choices=[]),
                ui.input_text_area("nouvelles_coordonnees",
                                   "Nouvelles coordonnées (une ligne par "
                                   "ligne, telles qu'écrites)", rows=4),
                ui.input_action_button("changer_famille",
                                       "Remplacer la famille du lot"),
            ),
            _etape(
                "Identité de la copropriété", "copropriete",
                ui.input_text("copro_nom", "Nom"),
                ui.input_text("copro_adresse", "Adresse"),
                ui.input_text("copro_contact", "Contact du syndic"),
                ui.input_action_button("maj_copropriete",
                                       "Enregistrer la copropriété"),
            ),
        ),
        ui.nav_panel(
            "Suivi des paiements",
            _etape(
                "Période suivie",
                ui.input_select("periode_suivi", "Période", choices=[]),
                ui.output_ui("suivi_etat"),
            ),
            _etape(
                "Encaissement (un paiement reçu)", "encaissement",
                ui.layout_columns(
