# ---------------------------------------------------------------------------
# Serveur
# ---------------------------------------------------------------------------


def server(input, output, session):
    class Etat:
        """État de session (posture D : rien ne survit à la session).

        - ``dossier`` : dossier chargé (ses octets portés par lui-même) ;
        - ``periode`` : clé de la période ouverte dans l'assistant ;
        - ``emissions`` : PDF produits en session {clé: {chemin: octets}} ;
        - ``persiste_a`` : longueur du journal au dernier point de
          persistance (chargement, Enregistrer, reprise) — au-delà, il y
          a des mutations non enregistrées (drapeau d'alerte, plan §E) ;
        - ``copie_envoyee_a`` : idem, côté sauvegarde automatique ;
        - ``lecture_seule`` : second onglet (verrou Q-G) — mutations
          refusées, aucune sauvegarde automatique ;
        - ``copies`` : copies de travail listées par le client (B-12) ;
        - ``libelle_dossier`` : nom du fichier ouvert (libellé des copies) ;
        - ``figage_en_attente`` : période dont le verrouillage attend la
          confirmation explicite (B-24).
        """

        dossier = None
        periode = None
        emissions = {}
        persiste_a = 0
        copie_envoyee_a = 0
        echeance = 0.0
        dernier_journal = 0
        sauvegarde_ok = None       # None = inconnu, True, False
        copies = []                # [{cle, horodatage, libelle, ancienne}]
        copie_horodatage = None    # dernière copie écrite
        libelle_dossier = None
        lecture_seule = False
        verrou_indisponible = False
        figage_en_attente = None
        tic_n = 0                  # compteur d'invalidation (non réactif)

    etat = Etat()
    tic = reactive.value(0)
    """``tic`` ne sert qu'à invalider les rendus après chaque changement
    d'état ; sa valeur est portée par un compteur Python ORDINAIRE :
    lire ``tic()`` depuis un effet (pour l'incrémenter) y enregistrerait
    une dépendance réactive et bouclerait l'effet sur lui-même."""

    def _bump():
        etat.tic_n = getattr(etat, "tic_n", 0) + 1
        tic.set(etat.tic_n)

    def _notifier(texte, type_="default"):
        ui.notification_show(texte, type=type_, duration=6)

    def _lecture_seule() -> bool:
        """Garde serveur du verrou d'onglet (Q-G) : le second onglet ne
        modifie jamais le dossier (ni la copie de travail)."""
        if etat.lecture_seule:
            _notifier(
                "Onglet en lecture seule : un autre onglet de "
                "l'application est ouvert. Fermez-le (ou cliquez "
                "« Réessayer en écriture »), puis recommencez.", "error")
            return True
        return False

    def _auteur():
        return revision.exiger_initiales(input.initiales())

    def _sources_fraiches():
        sources = {}
        for par_periode in etat.emissions.values():
            sources.update(par_periode)
        return sources

    def _horodatage_reel():
        return datetime.now(timezone.utc).isoformat(timespec="seconds")

    def _rafraichir_choix():
        if etat.dossier is None:
            return
        cles = sorted(etat.dossier.appels)
        par_etat = {cle: etat.dossier.appels[cle].etat.value
                    for cle in cles}
        libelles = {cle: f"{cle} ({par_etat[cle]})" for cle in cles}
        ui.update_select("periode_choisie", choices=libelles)
        ui.update_select("periode_suivi", choices=libelles)
        familles = etat.dossier.donnees["familles"]
        ui.update_select(
            "famille_lot",
            choices={f["identifiant"]:
                     f"{f['identifiant']} — "
                     f"{f.get('feuille') or '(feuille inconnue)'}"
                     for f in familles})
        lots = [f["identifiant"] for f in familles]
        ui.update_select("enc_lot", choices=lots)
        ui.update_select("cred_lot", choices=lots)
        copro = etat.dossier.donnees.get("copropriete") or {}
        ui.update_text("copro_nom", value=copro.get("nom") or "")
        ui.update_text("copro_adresse", value=copro.get("adresse") or "")
        ui.update_text("copro_contact", value=copro.get("contact") or "")

    # -- chargement du dossier (upload, D-0007) --------------------------

    @reactive.Effect
    async def _au_chargement():
        fichier = input.dossier_zip()
        if not fichier:
            return
        if etat.dossier is not None \
                and len(etat.dossier.journal) > etat.persiste_a:
            # B-04 (D-0043) : rouvrir un dossier ne jette plus le travail
            # en cours — refus tant que des saisies ne sont pas
            # enregistrées.
            _notifier("Des saisies ne sont pas enregistrées — "
                      "« Enregistrer » d'abord (ou fermez la session "
                      "pour tout abandonner) ; le dossier courant reste "
                      "ouvert.", "error")
            return
        # B-21 : refus avant lecture en mémoire d'un fichier démesuré.
        taille = int(fichier[0].get("size") or 0)
        if taille > revision.TAILLE_MAX_TOTAL:
            _notifier(
                "Dossier refusé : fichier de plus de "
                f"{revision.TAILLE_MAX_TOTAL // (1024 * 1024)} Mo — "
                "dossier illisible", "error")
            _bump()
            return
        with open(fichier[0]["datapath"], "rb") as flux:
            octets = flux.read()
        try:
            dossier = revision.charger_octets(octets)
        except Exception as exc:
            # B-04 : un fichier refusé ne ferme pas le dossier ouvert.
            message = getattr(exc, "message", str(exc))
            _notifier(f"Dossier refusé : {message}"
                      + (" — le dossier précédent reste ouvert."
                         if etat.dossier is not None else ""), "error")
            _bump()
            return
        etat.dossier = dossier
        revision.brancher_horloge(etat.dossier, _horodatage_reel)
        etat.periode = None
        etat.emissions = {}
        etat.persiste_a = len(etat.dossier.journal)
        etat.copie_envoyee_a = etat.persiste_a
        etat.dernier_journal = etat.persiste_a
        etat.figage_en_attente = None
        etat.libelle_dossier = str(fichier[0].get("name") or "")[:120] \
            or None
        _rafraichir_choix()
        _maj_tous_releves()
        # Q-G : le client connaît la clé de copie propre à ce dossier.
        await session.send_custom_message(
            "loft-copie",
            {"action": "identite",
             "cle": "travail:" + revision.identite_dossier(dossier),
             "libelle": etat.libelle_dossier or ""})
        # B-11 : la date de la dernière écriture du dossier est affichée
        # en clair — rouvrir une révision ancienne se voit.
        entrees = dossier.journal.entrees
        derniere = (" — dernière écriture le "
                    + str(entrees[-1].get("horodatage", "?"))[:16]
                    .replace("T", " à ")
                    + " par " + str(entrees[-1].get("auteur", "?"))
                    if entrees else " — journal vide")
        non_scellees = revision.periodes_non_scellees(etat.dossier)
        mention_scelles = (
            " — ATTENTION : " + str(len(non_scellees))
            + " période(s) non scellée(s), voir l'onglet « Intégrité & "
              "export »" if non_scellees else " — sceaux des périodes "
            "vérifiés")
        _notifier("Dossier ouvert — "
                  + str(len(etat.dossier.appels)) + " période(s), journal "
                  + str(len(etat.dossier.journal))
                  + " entrées (chaîne, empreinte de tête et empreintes "
                    "des PDF vérifiées)" + mention_scelles + derniere + ".")
        _bump()

    # -- sauvegarde automatique (copie de travail, plan §E) ---------------

    @reactive.Effect
    async def _sauvegarde_auto():
        reactive.invalidate_later(1.0)
        if etat.dossier is None or etat.lecture_seule:
            return
        journal = etat.dossier.journal
        nombre = len(journal)
        if nombre <= etat.copie_envoyee_a:
            etat.dernier_journal = nombre
            return
        if nombre != etat.dernier_journal:
            # B-25 (lot 12) : la temporisation court à partir de la
            # DERNIÈRE mutation — plus de reconstruction du ZIP à chaque
            # tour de boucle (un dossier de 100 Mo ne part plus 60 fois
            # par minute).
            etat.dernier_journal = nombre
            etat.echeance = time.time() + DEBOUNCE_SAUVEGARDE
            return
        if time.time() < etat.echeance:
            return
        try:
            octets = revision.octets_revision(etat.dossier,
                                              _sources_fraiches())
            horodatage = _horodatage_reel()
            await session.send_custom_message(
                "loft-copie",
                {"action": "ecrire",
                 "cle": "travail:" + revision.identite_dossier(etat.dossier),
                 "horodatage": horodatage,
                 "libelle": etat.libelle_dossier or "",
                 "b64": base64.b64encode(octets).decode("ascii")})
            etat.copie_envoyee_a = nombre
            etat.sauvegarde_ok = True
            etat.copie_horodatage = horodatage
            _bump()
        except Exception:
            etat.sauvegarde_ok = False
            etat.echeance = time.time() + DEBOUNCE_SAUVEGARDE
            _bump()

    # -- alerte avant fermeture (armée sur mutations non enregistrées) ---

    _derniere_alerte = {"armee": None}

    @reactive.Effect
    async def _alerte_client():
        tic()
        armee = (etat.dossier is not None and not etat.lecture_seule
                 and len(etat.dossier.journal) > etat.persiste_a)
        if armee != _derniere_alerte["armee"]:
            _derniere_alerte["armee"] = armee
            await session.send_custom_message("loft-alerte",
                                             {"armee": armee})

    # -- verrou d'onglet (Q-G) -------------------------------------------

    @reactive.Effect
    def _onglet():
        etat.lecture_seule = bool(input.loft_onglet_secondaire())
        if etat.lecture_seule:
            etat.figage_en_attente = None
        _bump()

    @reactive.Effect
    def _verrou_indisponible():
        etat.verrou_indisponible = bool(input.loft_verrou_indisponible())
        _bump()

    @reactive.Effect
    @reactive.event(input.reessayer_verrou)
    async def _reessayer_verrou():
        await session.send_custom_message("loft-copie",
                                          {"action": "reessayer_verrou"})
        _notifier("Vérification du verrou d'onglet — si l'autre onglet est "
                  "fermé, cet onglet reprend l'écriture.")

    # -- copies de travail (reprendre / jeter, plan §E — B-12) -----------

    @reactive.Effect
    def _copies():
        valeur = input.copies_travail()
        if valeur is None:
            return
        copies = valeur.get("copies") if isinstance(valeur, dict) else valeur
        etat.copies = [c for c in (copies or []) if isinstance(c, dict)]
        etat.copie_horodatage = (etat.copies[0].get("horodatage")
                                 if etat.copies else None)
        _bump()

    @reactive.Effect
    def _choix_copie():
        """Alimente la sélection de copie (contrôle statique, B-12)."""
        tic()
        choix = {c.get("cle"): f"{c.get('horodatage') or '?'} — "
                               f"{c.get('libelle') or 'copie'}"
                 for c in etat.copies if c.get("cle")}
        courante = input.copie_choisie()
        selection = courante if courante in choix else (
            next(iter(choix)) if choix else None)
        ui.update_select("copie_choisie", choices=choix,
                         selected=selection)

    @reactive.Effect
    @reactive.event(input.reprendre_copie)
    async def _reprendre_copie():
        if etat.dossier is not None \
                and len(etat.dossier.journal) > etat.persiste_a:
            _notifier("Des saisies ne sont pas enregistrées — "
                      "« Enregistrer » d'abord ; la copie de travail n'est "
                      "pas reprise (le travail en cours reste ouvert).",
                      "error")
            return
        cle = input.copie_choisie()
        if not cle:
            _notifier("Aucune copie de travail à reprendre.", "error")
            return
        await session.send_custom_message("loft-copie",
                                          {"action": "lire", "cle": cle})

    @reactive.Effect
    async def _copie_contenu():
        valeur = input.copie_travail_contenu()
        if not valeur or not valeur.get("b64"):
            return
        if etat.dossier is not None \
                and len(etat.dossier.journal) > etat.persiste_a:
            _notifier("Des saisies ne sont pas enregistrées — la copie "
                      "n'est pas reprise (le travail en cours reste "
                      "ouvert).", "error")
            return
        try:
            octets = base64.b64decode(valeur["b64"])
            dossier = revision.charger_octets(octets)
        except Exception as exc:
            _notifier(f"Copie de travail illisible : "
                      f"{getattr(exc, 'message', exc)}", "error")
            return
        etat.dossier = dossier
        revision.brancher_horloge(etat.dossier, _horodatage_reel)
        etat.emissions = {}
        etat.periode = None
        etat.figage_en_attente = None
        cle_copie = str(valeur.get("cle") or "")
        libelle = next((c.get("libelle") for c in etat.copies
                        if c.get("cle") == cle_copie), None)
        etat.libelle_dossier = libelle or etat.libelle_dossier
        # B-05 (D-0043) : une copie reprise n'est PAS présentée comme
        # enregistrée — le compteur montre tout le journal « non
        # enregistré » et l'alerte de fermeture reste armée jusqu'au
        # prochain « Enregistrer ».
        etat.persiste_a = 0
        etat.copie_envoyee_a = len(etat.dossier.journal)
        etat.dernier_journal = etat.copie_envoyee_a
        _rafraichir_choix()
        _maj_tous_releves()
        await session.send_custom_message(
            "loft-copie",
            {"action": "identite",
             "cle": "travail:" + revision.identite_dossier(etat.dossier),
             "libelle": etat.libelle_dossier or ""})
        _notifier("Copie de travail reprise — les saisies en cours sont "
                  "retrouvées (sauvegarde automatique). Rien n'est "
                  "enregistré : cliquez « Enregistrer » pour produire le "
                  "fichier maître.")
        _bump()

    @reactive.Effect
    @reactive.event(input.jeter_copie)
    async def _jeter_copie():
        cle = input.copie_choisie()
        if not cle:
            _notifier("Aucune copie de travail à jeter.", "error")
            return
        await session.send_custom_message("loft-copie",
                                          {"action": "effacer", "cle": cle})
        _notifier("Copie de travail jetée.")
        _bump()

    @reactive.Effect
    @reactive.event(input.jeter_toutes)
    async def _jeter_toutes():
        await session.send_custom_message("loft-copie",
                                          {"action": "effacer_tout"})
        _notifier("Toutes les copies de travail de ce navigateur ont été "
                  "jetées.")
        _bump()

    @reactive.Effect
    def _stockage():
        if input.loft_stockage_ok() is False:
            if etat.sauvegarde_ok is not False:
                etat.sauvegarde_ok = False
                _bump()

    # -- étape 1 : périodes ----------------------------------------------

    @reactive.Effect
    @reactive.event(input.creer_periode)
    def _creer():
        if _lecture_seule():
            return
        if etat.dossier is None:
            _notifier("Ouvrez d'abord le dossier.", "error")
            return
        try:
            auteur = _auteur()
            exercice = input.exercice()
            if exercice is None:  # B-20 : saisie obligatoire
                raise core.ErreurValidation(
                    "exercice obligatoire — saisissez l'année de la "
                    "période (ex. 2027)", "periode")
            cle = revision.creer_periode(
                etat.dossier, int(exercice), int(input.semestre()),
                auteur)
        except (core.ErreurValidation, ValueError, TypeError) as exc:
            _notifier(getattr(exc, "message", str(exc)), "error")
            return
        etat.periode = cle
        _maj_tous_releves()
        _bump()
        _notifier(f"Période {cle} créée (brouillon) — action enregistrée "
                  f"au journal par {auteur}.")

    @reactive.Effect
    @reactive.event(input.ouvrir_periode)
    def _ouvrir():
        if etat.dossier is None:
            _notifier("Ouvrez d'abord le dossier.", "error")
            return
        cle = input.periode_choisie()
        if not cle:
            return
        etat.periode = cle
        _maj_tous_releves()
        _bump()
        _notifier(f"Période {cle} ouverte "
                  f"({etat.dossier.appels[cle].etat.value}).")

    # -- étape 2 : factures ----------------------------------------------

    @reactive.Effect
    @reactive.event(input.ajouter_facture)
    def _ajouter_facture():
        if _lecture_seule():
            return
        if etat.dossier is None or etat.periode is None:
            _notifier("Ouvrez (ou créez) d'abord une période (étape 1).",
                      "error")
            return
        try:
            auteur = _auteur()
            mode = None
            if input.fact_mode() != MODE_DEFAUT:
                mode = core.ModeRepartition.de_libelle(input.fact_mode())
            montant = input.fact_montant()
            identifiant = revision.ajouter_facture(
                etat.dossier, etat.periode,
                {"type_charge": core.TypeCharge.de_libelle(
                    input.fact_type()),
                 "montant": montant,
                 "fournisseur": input.fact_fournisseur(),
                 "detail": input.fact_detail(),
                 "date_facture": input.fact_date(),
                 "mode": mode},
                auteur)
        except core.ErreurValidation as exc:
            _notifier(exc.message, "error")
            return
        _bump()
        _notifier(f"Facture {identifiant} ajoutée ({montant} €) — action "
                  "enregistrée au journal (la date est obligatoire à la "
                  "saisie).")

    # -- étape 2 : correction d'une facture (D-0036 — lot 7) -----------

    def _preremplir_facture(f):
        """Recharge une facture existante dans le formulaire de saisie."""
        ui.update_text("fact_fournisseur", value=f.fournisseur or "")
        ui.update_select("fact_type",
                         selected=f.type_charge.value)
        ui.update_text("fact_detail", value=f.detail or "")
        ui.update_text("fact_montant", value=core.euros(f.montant_centimes))
        ui.update_select("fact_mode",
                         selected=(f.mode.value if f.mode
                                   else MODE_DEFAUT))
        ui.update_text("fact_date",
                       value=(f.date_facture.isoformat()
                              if f.date_facture else ""))

    @reactive.Effect
    def _au_choix_facture_a_corriger():
        identifiant = input.facture_a_corriger()
        if not identifiant or etat.dossier is None or etat.periode is None:
            return
        appel = etat.dossier.appels.get(etat.periode)
        f = appel.factures.get(identifiant) if appel is not None else None
        if f is None:
            return
        _preremplir_facture(f)
        _notifier(f"Facture {identifiant} chargée dans le formulaire — "
                  "modifiez les champs puis cliquez "
                  "« Corriger la facture ».")

    @reactive.Effect
    @reactive.event(input.corriger_facture)
    def _corriger_facture():
        if _lecture_seule():
            return
        if etat.dossier is None or etat.periode is None:
            _notifier("Ouvrez (ou créez) d'abord une période (étape 1).",
                      "error")
            return
        identifiant = input.facture_a_corriger()
        if not identifiant:
            _notifier("Choisissez d'abord la facture à corriger dans la "
                      "liste.", "error")
            return
        try:
            auteur = _auteur()
            mode = None
            if input.fact_mode() != MODE_DEFAUT:
                mode = core.ModeRepartition.de_libelle(input.fact_mode())
            montant = input.fact_montant()
            revision.corriger_facture(
                etat.dossier, etat.periode, identifiant,
                {"type_charge": core.TypeCharge.de_libelle(
                    input.fact_type()),
                 "montant": montant,
                 "fournisseur": input.fact_fournisseur(),
                 "detail": input.fact_detail(),
                 "date_facture": input.fact_date(),
                 "mode": mode},
                auteur)
        except core.ErreurValidation as exc:
            _notifier(exc.message, "error")
            return
        _bump()
        _notifier(f"Facture {identifiant} corrigée ({montant} €) — action "
                  "enregistrée au journal ; la saisie précédente y reste "
                  "visible.")

    # -- étape 3 : relevés d'eau ------------------------------------------

    @reactive.Effect
    @reactive.event(input.enregistrer_date_releve)
    def _dater_releve():
        if _lecture_seule():
            return
        if etat.dossier is None or etat.periode is None:
            _notifier("Ouvrez (ou créez) d'abord une période (étape 1).",
                      "error")
            return
        try:
            revision.definir_date_releve(etat.dossier, etat.periode,
                                         input.date_releve(), _auteur())
        except core.ErreurValidation as exc:
            _notifier(exc.message, "error")
            return
        _bump()
        _notifier("Date du relevé enregistrée — action enregistrée au "
                  "journal.")

    def _maj_releve(lot: str) -> None:
        """Pré-remplit la ligne d'un lot (chaînage : dernier relevé connu,
        étape 3). Ne touche QUE ce lot — la saisie en cours des autres
        lignes n'est jamais écrasée."""
        if etat.dossier is None:
            return
        appel = etat.dossier.appels.get(etat.periode)
        deja = appel.releves.get(lot) if appel is not None else None
        connu = revision.dernier_releve_connu(etat.dossier, lot,
                                              etat.periode) or {}
        ui.update_text(
            f"compteur_{lot}",
            value=(deja.compteur if deja is not None
                   else connu.get("compteur")) or "")
        ui.update_text(
            f"ancien_{lot}",
            value=(str(deja.ancien_index) if deja is not None
                   else connu.get("ancien")) or "")
        ui.update_text(
            f"nouvel_{lot}",
            value=str(deja.nouvel_index) if deja is not None else "")
        ui.update_checkbox(f"remplacement_{lot}",
                           value=bool(deja.remplacement)
                           if deja is not None else False)

    def _maj_tous_releves() -> None:
        if etat.dossier is None:
            return
        for f in etat.dossier.donnees["familles"]:
            _maj_releve(f["identifiant"])

    def _fabrique_releve(lot):
        bouton = getattr(input, f"releve_{lot}")

        @reactive.Effect
        @reactive.event(bouton)
        def _saisie():
            if _lecture_seule():
                return
            if etat.dossier is None or etat.periode is None:
                _notifier("Ouvrez (ou créez) d'abord une période (étape 1).",
                          "error")
                return
            try:
                auteur = _auteur()
                appel = etat.dossier.appels[etat.periode]
                # le bouton « Enregistrer » de la ligne fait addition OU
                # correction (D-0036, lot 7 — arbitrage Q3 de la gate) :
                # ressaisir un lot déjà relevé corrige son relevé (la
                # saisie précédente reste au journal).
                deja = appel.releves.get(lot)
                if deja is None:
                    revision.ajouter_releve(
                        etat.dossier, etat.periode, lot,
                        getattr(input, f"compteur_{lot}")(),
                        getattr(input, f"ancien_{lot}")(),
                        getattr(input, f"nouvel_{lot}")(),
                        getattr(input, f"remplacement_{lot}")(),
                        auteur)
                    _notifier(f"Relevé du lot {lot} enregistré.")
                else:
                    revision.corriger_releve(
                        etat.dossier, etat.periode, lot,
                        getattr(input, f"compteur_{lot}")(),
                        getattr(input, f"ancien_{lot}")(),
                        getattr(input, f"nouvel_{lot}")(),
                        getattr(input, f"remplacement_{lot}")(),
                        auteur)
                    _notifier(f"Relevé du lot {lot} corrigé — action "
                              "enregistrée au journal.")
            except core.ErreurValidation as exc:
                _notifier(exc.message, "error")
                return
            _maj_releve(lot)  # la ligne reflète le relevé persisté
            _bump()
        return _saisie

    def _fabrique_statut_releve(lot):
        def _statut():
            return _statut_releve(lot)

        _statut.__name__ = f"releve_statut_{lot}"
        return render.ui(_statut)

    def _statut_releve(lot):
        tic()
        if etat.dossier is None or etat.periode is None:
            return ui.span({"style": "color:#888; font-size:0.85em;"},
                           "aucune période active")
        appel = etat.dossier.appels[etat.periode]
        deja = appel.releves.get(lot)
        if deja is not None:
            # signal clair de la correction (D-0036, arbitrage Q3) :
            # ressaisir la ligne corrige le relevé en brouillon.
            if appel.etat is core.EtatAppel.BROUILLON:
                return ui.span(
                    {"class": "badge b-emis",
                     "style": "font-size:0.85em;"},
                    "relevé saisi — " + str(deja.consommation_m3)
                    + " m³ (ressaisir la ligne pour corriger)")
            return ui.span(
                {"class": "badge b-emis", "style": "font-size:0.85em;"},
                "relevé saisi — " + str(deja.consommation_m3) + " m³")
        connu = revision.dernier_releve_connu(etat.dossier, lot,
                                              etat.periode) or {}
        return ui.span(
            {"style": "color:#888; font-size:0.85em;"},
            "chaînage : ancien index du dernier relevé connu"
            if connu.get("ancien") else
            "aucun relevé antérieur — saisissez l'ancien index")

    # -- étape 5 : émission, envois semi-manuels (D-0001) -----------------

    @reactive.Effect
    @reactive.event(input.emettre)
    def _emettre():
        if _lecture_seule():
            return
        if etat.dossier is None or etat.periode is None:
            _notifier("Ouvrez d'abord une période (étape 1).", "error")
            return
        try:
            auteur = _auteur()
            sources = revision.emettre_periode(etat.dossier, etat.periode,
                                               auteur)
        except Exception as exc:
            # B-02 (D-0043) : l'émission est atomique — aucun état n'a
            # changé ; toute erreur devient une notification, jamais une
            # fermeture de session (le rattrapage large n'est permis QUE
            # parce que l'atomicité garantit zéro effet de bord).
            _notifier("Émission impossible : "
                      + getattr(exc, "message", str(exc))
                      + " — la période reste en brouillon, rien n'a été "
                        "enregistré.", "error")
            return
        etat.emissions[etat.periode] = sources
        _bump()
        _notifier(f"Appel émis — {len(sources)} PDF produits (un par lot, "
                  "ex. F1-2100-S1.pdf).")

    def _fabrique_envoye(lot):
        bouton = getattr(input, f"envoye_{lot}")
        bouton_annuler = getattr(input, f"annuler_envoye_{lot}")

        @reactive.Effect
        @reactive.event(bouton)
        def _marquage():
