    @render.ui
    def zone_correction_facture():
        """Correction d'une facture (D-0036 — lot 7) : uniquement en
        brouillon (le noyau refuse ailleurs de toute façon) ; choisir la
        facture recharge le formulaire de saisie."""
        tic()
        if etat.dossier is None or etat.periode is None:
            return None
        appel = etat.dossier.appels[etat.periode]
        if appel.etat is not core.EtatAppel.BROUILLON or not appel.factures:
            return None
        choix = {f.identifiant:
                 f"{f.identifiant} — {f.fournisseur} "
                 f"({f.type_charge.value})"
                 for f in appel.factures.values()}
        courante = input.facture_a_corriger()
        ui.update_select("facture_a_corriger", choices=choix,
