"""Calculs de l'appel de fonds : les 4 modes, montant copropriété, débits,
totaux, soldes et contrôles (plan §4.3, §4.9).

Sémantique calée sur les formules ODS (P4/P5, D-0016) :

- « Tantièmes » : répartition au plus fort reste entre les lots
  copropriété, poids = tantièmes ; les lots hors copropriété touchent 0.
- « 1/6ème » : parts égales entre les lots copropriété — généralisé en
  E/n, n = nombre de lots copropriété (n = 6 dans l'ODS).
- « Tantièmes + 1/7ème » (D-0023, schéma à deux niveaux) : le lot hors
  copropriété (exactement un, validé) touche l'arrondi arithmétique de
  E/7 ; le complément E − part est réparti entre les lots copropriété au
  plus fort reste sur les tantièmes. Le montant copropriété
  (« E − E/7 » dans l'ODS) reste exact au centime près.
- « Consommation réelle » (D-0017) : tous les lots pourvus d'un relevé,
  poids = m³ en litres entiers (index à trois décimales).

Montant copropriété = E − Σ(parts des lots hors copropriété), dérivé,
jamais saisi (plan §4.3) ; solde = débit − Σ crédits (D-0020).
"""
# This file is part of loftRv2 — lot 3 (noyau métier pur Python).

from dataclasses import dataclass, field
from decimal import Decimal

from core.erreurs import Avertissement, ErreurValidation
from core.modeles import (ModeRepartition, Periode, TypeCharge)
from core.montants import arrondi_arithmetique, repartir_plus_fort_reste

SEPTIEME = Decimal(7)


def _poids_tantiemes(lots_copro) -> dict:
    poids = {}
    for f in lots_copro:
        if f.tantiemes is None or f.tantiemes <= 0:
            raise ErreurValidation(
                f"tantièmes manquants pour le lot copropriété "
                f"{f.identifiant} (mode tantièmes)",
                "tantiemes",
            )
        poids[f.identifiant] = f.tantiemes
    if not poids:
        raise ErreurValidation(
            "aucun lot copropriété pourvu de tantièmes", "tantiemes"
        )
    return poids


def parts_mode_tantiemes(total_centimes: int, referentiel) -> dict:
    """Mode « Tantièmes » : lots copropriété seulement, poids = tantièmes."""
    poids = _poids_tantiemes(referentiel.lots_copro())
    parts = {f.identifiant: 0 for f in referentiel.familles}
    parts.update(repartir_plus_fort_reste(total_centimes, poids))
    return parts


def parts_mode_sixieme(total_centimes: int, referentiel) -> dict:
    """Mode « 1/6ème » : parts égales entre les lots copropriété (E/n)."""
    lots = referentiel.lots_copro()
    if not lots:
        raise ErreurValidation(
            "aucun lot copropriété pour le mode 1/6ème", "mode"
        )
    poids = {f.identifiant: 1 for f in lots}
    parts = {f.identifiant: 0 for f in referentiel.familles}
    parts.update(repartir_plus_fort_reste(total_centimes, poids))
    return parts


def parts_mode_tantiemes_septieme(total_centimes: int, referentiel) -> dict:
    """Mode « Tantièmes + 1/7ème » — schéma à deux niveaux (D-0023).

    Niveau 1 : le lot hors copropriété touche l'arrondi arithmétique de
    E/7 (k/7 ne donne jamais un demi-centime exact : arrondi sans
    ambiguïté). Niveau 2 : le complément est réparti entre les lots
    copropriété au plus fort reste sur les tantièmes.
    """
    hors_copro = referentiel.lots_hors_copro()
    if len(hors_copro) != 1:
        raise ErreurValidation(
            f"le mode « Tantièmes + 1/7ème » exige exactement un lot hors "
            f"copropriété ({len(hors_copro)} trouvé(s))",
            "mode",
        )
    lot_hors = hors_copro[0]
    e = int(total_centimes)
    part_hors = arrondi_arithmetique(Decimal(e) / SEPTIEME)
    complement = e - part_hors
    poids = _poids_tantiemes(referentiel.lots_copro())
    parts = {f.identifiant: 0 for f in referentiel.familles}
    parts.update(repartir_plus_fort_reste(complement, poids))
    parts[lot_hors.identifiant] = part_hors
    if sum(parts.values()) != e:  # pragma: no cover — invariant interne
        raise ErreurValidation(
            "invariant rompu : somme des parts != facture", "repartition"
        )
    return parts


def parts_mode_consommation_reelle(total_centimes: int, referentiel,
                                   releves: dict) -> dict:
    """Mode « Consommation réelle » : tous les lots, poids = litres (D-0017).

    Requiert un relevé complet (chaque lot) et une consommation totale
    strictement positive — sinon erreur bloquante (plan §4.9).
    """
    manquants = [f.identifiant for f in referentiel.familles
                 if f.identifiant not in releves]
    if manquants:
        raise ErreurValidation(
            "relevés d'eau incomplets pour la consommation réelle : lots "
            + ", ".join(manquants),
            "releve",
        )
    poids = {}
    for identifiant, releve in releves.items():
        litres = releve.consommation_litres
        if litres <= 0:
            continue  # consommation nulle : lot non participant (avertissement)
        poids[identifiant] = litres
    if not poids:
        raise ErreurValidation(
            "consommation d'eau totale nulle : répartition impossible",
            "releve",
        )
    parts = {f.identifiant: 0 for f in referentiel.familles}
    parts.update(repartir_plus_fort_reste(int(total_centimes), poids))
    return parts


def parts_facture(facture, referentiel, releves: dict) -> dict:
    """Parts (centimes) d'une facture par lot, selon son mode effectif.

    Retourne une part pour CHAQUE lot du référentiel (0 pour les
    non-participants) — le montant copropriété se dérive ainsi sans
    cas particulier.
    """
    mode = facture.mode_effectif(referentiel)
    e = facture.montant_centimes
    if mode is ModeRepartition.TANTIEMES:
        return parts_mode_tantiemes(e, referentiel)
    if mode is ModeRepartition.SIXIEME:
        return parts_mode_sixieme(e, referentiel)
    if mode is ModeRepartition.TANTIEMES_SEPTIEME:
        return parts_mode_tantiemes_septieme(e, referentiel)
    if mode is ModeRepartition.CONSOMMATION_REELLE:
        return parts_mode_consommation_reelle(e, referentiel, releves)
    raise ErreurValidation(  # pragma: no cover — enum fermée
        f"mode de répartition inconnu : {mode!r}", "mode"
    )


def montant_copropriete(parts: dict, referentiel) -> int:
    """Part de la facture portée par les lots copropriété : somme des parts
    des lots copropriété (équivalent exact de « facture − parts des lots
    hors copropriété », plan §4.3)."""
    return sum(parts[f.identifiant] for f in referentiel.lots_copro())


# ---------------------------------------------------------------------------
# Résultat d'un appel complet
# ---------------------------------------------------------------------------


@dataclass
class LigneFacture:
    """Résultat d'une facture : parts par lot + montant copropriété dérivé."""

    facture: object
    parts: dict
    montant_copro: int

    def to_dict(self) -> dict:
        return {
            "facture": self.facture.identifiant,
            "type": self.facture.type_charge.value,
            "montant_centimes": self.facture.montant_centimes,
            "parts": dict(self.parts),
            "montant_copro_centimes": self.montant_copro,
        }


@dataclass
class ResultatAppel:
    """Résultat calculé d'un appel de fonds (centimes entiers partout)."""

    lignes: list = field(default_factory=list)
    total_facture: int = 0
    total_copropriete: int = 0
    debit_par_lot: dict = field(default_factory=dict)
    credit_par_lot: dict = field(default_factory=dict)
    solde_par_lot: dict = field(default_factory=dict)
    encaisse_par_lot: dict = field(default_factory=dict)


def calculer_appel(appel) -> ResultatAppel:
    """Calcule l'appel complet : parts par facture, montant copropriété,
    débits par lot (Σ des parts), crédits (Σ ajustements), soldes
    (débit − Σ crédits, D-0020) et encaissements suivis.
    """
    referentiel = appel.referentiel
    releves = appel.releves
    resultat = ResultatAppel()
    debit = {f.identifiant: 0 for f in referentiel.familles}
    for facture in appel.factures.values():
        parts = parts_facture(facture, referentiel, releves)
        copro = montant_copropriete(parts, referentiel)
        resultat.lignes.append(
            LigneFacture(facture=facture, parts=parts, montant_copro=copro)
        )
        resultat.total_facture += facture.montant_centimes
        resultat.total_copropriete += copro
        for lot, part in parts.items():
            debit[lot] += part
    resultat.debit_par_lot = debit
    resultat.credit_par_lot = {
        f.identifiant: 0 for f in referentiel.familles
    }
    for ajustement in appel.ajustements:
        resultat.credit_par_lot[ajustement.lot] += ajustement.montant_centimes
    resultat.solde_par_lot = {
        lot: debit[lot] - resultat.credit_par_lot[lot]
        for lot in debit
    }
    resultat.encaisse_par_lot = {
        f.identifiant: 0 for f in referentiel.familles
    }
    for encaissement in appel.encaissements:
        if encaissement.paye and encaissement.montant_centimes:
            resultat.encaisse_par_lot[encaissement.lot] += (
                encaissement.montant_centimes
            )
    return resultat


def debit_eau_par_lot(resultat: ResultatAppel) -> dict:
    """Débits d'eau par lot : parts des factures de type Eau (l'égalité
    avec la table de facturation de l'ODS est vérifiée au rapprochement)."""
    debit = {}
    for ligne in resultat.lignes:
        if ligne.facture.type_charge is TypeCharge.EAU:
            for lot, part in ligne.parts.items():
                debit[lot] = debit.get(lot, 0) + part
    return debit


# ---------------------------------------------------------------------------
# Contrôles : erreurs bloquantes et avertissements (plan §4.9)
# ---------------------------------------------------------------------------


def _verifier_facture(facture, referentiel, releves, periode, erreurs, avertis):
    if facture.montant_centimes <= 0:
        erreurs.append(
            ErreurValidation(
                f"facture {facture.identifiant} : montant <= 0", "montant"
            )
        )
    if facture.date_facture is None:
        avertis.append(
            Avertissement(
                "date_absente",
                f"facture {facture.identifiant} : date de facture absente",
            )
        )
    elif not periode.contient(facture.date_facture):
        avertis.append(
            Avertissement(
                "date_hors_periode",
                f"facture {facture.identifiant} : date "
                f"{facture.date_facture.isoformat()} hors de la période "
                f"{periode.cle}",
            )
        )
    try:
        parts_facture(facture, referentiel, releves)
    except ErreurValidation as exc:
        erreurs.append(exc)


def valider_appel(appel):
    """Contrôle complet de l'appel : retourne (erreurs, avertissements).

    Erreurs bloquantes (l'émission les refuse) : montant <= 0, mode
    inconnu (soulevé à la saisie), tantièmes manquants, plus d'un lot hors
    copropriété en T+1/7, Σm³ nul, nouvel < ancien sans remplacement,
    relevés incomplets pour une facture en consommation réelle, crédit <= 0
    ou sans motif. Avertissements (arbitrés par le syndic, D-0025) : date
    absente ou hors période, encaissement supérieur au solde, index
    inchangé.
    """
    erreurs = []
    avertissements = []
    referentiel = appel.referentiel
    periode = appel.periode
    releves = appel.releves

    for facture in appel.factures.values():
        _verifier_facture(facture, referentiel, releves, periode,
                          erreurs, avertissements)

    for identifiant, releve in releves.items():
        litres = releve.consommation_litres
        if litres < 0:
            # B-07 : compteur remplacé — la consommation négative ferait
            # payer l'eau du lot par les autres, en silence (les poids
            # <= 0 sont ignorés par la répartition).
            erreurs.append(
                ErreurValidation(
                    f"relevé du lot {identifiant} : consommation "
                    "négative — si le compteur a été remplacé, l'ancien "
                    "index est celui affiché par le compteur retiré ; "
                    "sinon, corrigez l'index saisi (étape 3)",
                    "releve",
                )
            )
        if litres == 0:
            avertissements.append(
                Avertissement(
                    "index_inchange",
                    f"relevé du lot {identifiant} : index inchangé "
                    "(consommation nulle)",
                )
            )
        if not releve.remplacement and releve.nouvel_index < releve.ancien_index:
            erreurs.append(
                ErreurValidation(
                    f"relevé du lot {identifiant} : nouvel index < ancien "
                    "sans remplacement",
                    "releve",
                )
            )

    for ajustement in appel.ajustements:
        if ajustement.montant_centimes <= 0:
            erreurs.append(
                ErreurValidation(
                    f"crédit du lot {ajustement.lot} : montant <= 0", "credit"
                )
            )
        if ajustement.motif is None:  # pragma: no cover — modèle déjà validé
            erreurs.append(
                ErreurValidation(
                    f"crédit du lot {ajustement.lot} : sans motif", "credit"
                )
            )

    if not erreurs:
        # les avertissements d'encaissement et de crédit exigent des
        # soldes fiables : ils ne sont évalués que sur un appel sans
        # erreur bloquante
        resultat = calculer_appel(appel)
        lots_deja_avertis = set()
        lots_credit_avertis = set()
        for lot in (f.identifiant for f in referentiel.familles):
            # B-18 (lot 12) : un crédit sans borne peut inverser le solde
            # sans le moindre signal — avertissement non bloquant.
            debit = resultat.debit_par_lot.get(lot, 0)
            credit = resultat.credit_par_lot.get(lot, 0)
            if credit > debit and lot not in lots_credit_avertis:
                avertissements.append(
                    Avertissement(
                        "credit_superieur_debit",
                        f"lot {lot} : crédits ({credit} centimes) "
                        f"supérieurs au débit ({debit} centimes) — vérifiez "
                        "le montant ou le motif du crédit",
                    )
                )
                lots_credit_avertis.add(lot)
        for encaissement in appel.encaissements:
            lot = encaissement.lot
            if not encaissement.paye or lot in lots_deja_avertis:
                continue
            solde = resultat.solde_par_lot.get(lot, 0)
            encaisse = resultat.encaisse_par_lot.get(lot, 0)
            if encaisse > solde:
                avertissements.append(
                    Avertissement(
                        "encaissement_superieur_solde",
                        f"lot {lot} : encaissements ({encaisse} centimes) "
                        f"supérieurs au solde ({solde} centimes) — à arbitrer "
                        "(typiquement via un crédit « excédent »)",
                    )
                )
                lots_deja_avertis.add(lot)
    return erreurs, avertissements

"""Journal de traçabilité en ajout seul, chaîné par empreintes (§4.4-4.5).

Chaque entrée porte : index, horodatage ISO 8601, auteur (initiales,
D-0019), action, détails, empreinte de l'entrée précédente et sa propre
empreinte. L'empreinte d'une entrée est le SHA-256 du JSON canonique de
l'entrée **sans** son propre champ ``empreinte`` (clés triées, séparateurs
fixes, UTF-8) — une entrée ne peut pas contenir son propre hash.

Déterminisme (plan §3) : JSON canonique (clés triées), séparateurs fixes,
UTF-8, horodatage explicitement fourni par les tests et la migration ;
aucune source d'aléa. La chaîne se vérifie intégralement et détecte toute
réécriture, réordonnancement ou troncature.
"""
# This file is part of loftRv2 — lot 3 (noyau métier pur Python).

import hashlib
import json
from datetime import datetime, timezone

from core.modeles import valider_auteur

EMPREINTE_GENESIS = ""


def json_canonique(charge: dict) -> str:
    """JSON canonique : clés triées, séparateurs compacts, UTF-8 exact."""
    return json.dumps(charge, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=False)


def empreinte(charge: dict) -> str:
    """SHA-256 du JSON canonique de la charge (hexadécimal minuscule)."""
    return hashlib.sha256(json_canonique(charge).encode("utf-8")).hexdigest()


def horodatage_courant() -> str:
    """Horodatage ISO 8601 UTC (seconde) — par défaut des nouvelles entrées.

    Les tests et la migration fournissent un horodatage explicite pour la
    reproductibilité ; ce défaut ne sert qu'aux saisies interactives.
    """
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


class Journal:
    """Journal en ajout seul. ``ajouter`` ne modifie jamais les entrées
    existantes ; aucune API de suppression ou de réécriture n'existe.

    ``horloge`` (optionnel) : fonction retournant un horodatage ISO 8601 —
    injectée par les tests pour des empreintes reproductibles (plan §3,
    « tests à horodatages fixes ») ; par défaut, l'heure UTC courante.
    """

    def __init__(self, entrees: list = None, horloge=None):
        self.entrees: list = list(entrees) if entrees else []
        self.horloge = horloge

    def __len__(self):
        return len(self.entrees)

    def ajouter(self, action: str, auteur: str, details: dict,
                horodatage: str = None) -> str:
        """Ajoute une entrée chaînée ; retourne son empreinte.

        ``details`` doit être sérialisable en JSON canonique (dict simple).
        """
        valider_auteur(auteur)
        if not action:
            raise ValueError("action de journal vide")
        precedente = (
            self.entrees[-1]["empreinte"] if self.entrees else EMPREINTE_GENESIS
        )
        if horodatage is None:
            horodatage = self.horloge() if self.horloge else horodatage_courant()
        entree = {
            "index": len(self.entrees),
            "horodatage": horodatage,
            "auteur": auteur,
            "action": action,
            "details": details if details is not None else {},
            "empreinte_precedente": precedente,
        }
        entree["empreinte"] = empreinte(entree)
        self.entrees.append(entree)
        return entree["empreinte"]

    def verifier(self) -> bool:
        """Vrai ssi la chaîne est intacte : indexes consécutifs, chaque
        empreinte recalculée identique, chaque chaînage correct.
        """
        return not self.anomalies()

    def anomalies(self) -> list:
        """Liste des ruptures de chaîne détectées (vide = journal sain)."""
        probleme = []
        precedente = EMPREINTE_GENESIS
        for attendu, entree in enumerate(self.entrees):
            if entree.get("index") != attendu:
                probleme.append(
                    f"entrée {attendu} : index {entree.get('index')!r} inattendu"
                )
            if entree.get("empreinte_precedente") != precedente:
                probleme.append(
                    f"entrée {attendu} : chaînage rompu "
                    f"(attendu {precedente[:12]}…, trouvé "
                    f"{str(entree.get('empreinte_precedente'))[:12]}…)"
                )
            charge = {k: v for k, v in entree.items() if k != "empreinte"}
            calculee = empreinte(charge)
            if entree.get("empreinte") != calculee:
                probleme.append(
                    f"entrée {attendu} : empreinte falsifiée "
                    f"(recalculée {calculee[:12]}…)"
                )
            precedente = entree.get("empreinte", "")
        return probleme

    def to_dict(self) -> list:
        """Sérialisation simple (lot 4 : dossier)."""
        return [dict(e) for e in self.entrees]

    @classmethod
    def from_dict(cls, data: list) -> "Journal":
        """Recharge un journal ; ``verifier()`` doit être appelé par le
        consommateur avant tout ajout (détection de falsification).
        """
        return cls(entrees=data)

"""Modèles du noyau métier — période, familles, factures, relevés, suivis.

Le noyau ne connaît aucune famille réelle, aucun nom, aucune adresse :
les identifiants sont stables et abstraits (convention F1…F7 à l'import,
stratégie §4.3 ; D-0002). Les montants sont des centimes entiers (D-0009),
les index d'eau des ``Decimal`` à trois décimales (poids en litres).

Chaque modèle expose ``to_dict``/``from_dict`` simples pour rester
consommable par le lot 4 (dossier) sans réouverture du noyau.
"""
# This file is part of loftRv2 — lot 3 (noyau métier pur Python).

import re
from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal
from enum import Enum

from core.erreurs import ErreurEtatPeriode, ErreurValidation
from core.montants import vers_centimes

REGLE_AUTEUR = re.compile(r"^[A-Z]{2,4}$")
"""Auteur déclaré = initiales, 2 à 4 lettres majuscules (D-0019)."""

JOURS_PAR_MOIS = {1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
                  7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}


def valider_auteur(auteur: str) -> str:
    """Valide les initiales de l'auteur déclaré (D-0019), sinon erreur."""
    if not isinstance(auteur, str) or not REGLE_AUTEUR.match(auteur):
        raise ErreurValidation(
            f"auteur hors convention (initiales 2-4 majuscules) : {auteur!r}",
            "auteur",
        )
    return auteur


