# Période (exercice + semestre, explicite — plan §4.5)
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class Periode:
    """Période explicite d'un appel de fonds : exercice + semestre S1/S2."""

    exercice: int
    semestre: int

    def __post_init__(self):
        if self.semestre not in (1, 2):
            raise ErreurValidation(
                f"semestre invalide (1 ou 2) : {self.semestre!r}", "periode"
            )
        if not isinstance(self.exercice, int) or not 2000 <= self.exercice <= 2100:
            raise ErreurValidation(
                f"exercice invalide : {self.exercice!r}", "periode"
            )

    @property
    def cle(self) -> str:
        return f"{self.exercice}-S{self.semestre}"

    @property
    def debut(self) -> date:
        return date(self.exercice, 1 if self.semestre == 1 else 7, 1)

    @property
    def fin(self) -> date:
        mois = 6 if self.semestre == 1 else 12
        annee = self.exercice if self.semestre == 1 else self.exercice
        return date(annee, mois, JOURS_PAR_MOIS[mois])

    def contient(self, valeur: date) -> bool:
        return self.debut <= valeur <= self.fin

    def to_dict(self) -> dict:
        return {"exercice": self.exercice, "semestre": self.semestre}

    @classmethod
    def from_dict(cls, data: dict) -> "Periode":
        return cls(exercice=int(data["exercice"]), semestre=int(data["semestre"]))


