class ModeRepartition(Enum):
    """Les 4 modes de répartition, libellés saisis en clair dans l'ODS."""

    TANTIEMES = "Tantièmes"
    SIXIEME = "1/6ème"
    TANTIEMES_SEPTIEME = "Tantièmes + 1/7ème"
    CONSOMMATION_REELLE = "Consommation réelle"

    @classmethod
    def de_libelle(cls, libelle: str) -> "ModeRepartition":
        try:
            return cls(libelle)
        except ValueError:
            raise ErreurValidation(
                f"mode de répartition inconnu : {libelle!r}", "mode"
            ) from None


class TypeCharge(Enum):
    """Types de charge de la copropriété (stratégie §2.2 — six types)."""

    POMPES = "Pompes"
    ASSURANCE = "Assurance"
    EAU = "Eau"
    BANQUE = "Banque"
    ELECTRICITE = "Électricité"
    PORTAIL = "Portail"

    @classmethod
    def de_libelle(cls, libelle: str) -> "TypeCharge":
        try:
            return cls(libelle)
        except ValueError:
            raise ErreurValidation(
                f"type de charge inconnu : {libelle!r}", "type_charge"
            ) from None


REGLES_DEFAUT: dict = {
    TypeCharge.POMPES: ModeRepartition.TANTIEMES_SEPTIEME,
    TypeCharge.ELECTRICITE: ModeRepartition.TANTIEMES_SEPTIEME,
    TypeCharge.BANQUE: ModeRepartition.SIXIEME,
    TypeCharge.PORTAIL: ModeRepartition.SIXIEME,
    TypeCharge.EAU: ModeRepartition.CONSOMMATION_REELLE,
    TypeCharge.ASSURANCE: ModeRepartition.TANTIEMES,
}
"""Règles par défaut par type de charge, telles que confirmées par l'oracle
ODS (D-0016) : pompes et électricité au « Tantièmes + 1/7ème », banque et
portail au « 1/6ème », eau à la consommation réelle, assurance aux tantièmes.
La config du brouillon (repartitions.csv) est fausse et n'est pas reprise."""


