@dataclass
class Famille:
    """Un lot (famille) : identifiant stable abstrait, drapeau copropriété,
    tantièmes (entier, requis pour les lots copropriété des modes tantièmes).
    """

    identifiant: str
    copropriete: bool = True
    tantiemes: int = None

    def __post_init__(self):
        if not self.identifiant or not isinstance(self.identifiant, str):
            raise ErreurValidation(
                f"identifiant de lot requis : {self.identifiant!r}", "lot"
            )
        if self.tantiemes is not None:
            if not isinstance(self.tantiemes, int) or self.tantiemes <= 0:
                raise ErreurValidation(
                    f"tantièmes invalides pour {self.identifiant} : "
                    f"{self.tantiemes!r}",
                    "tantiemes",
                )

    def to_dict(self) -> dict:
        return {
            "identifiant": self.identifiant,
            "copropriete": self.copropriete,
            "tantiemes": self.tantiemes,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Famille":
        return cls(
            identifiant=data["identifiant"],
            copropriete=bool(data.get("copropriete", True)),
            tantiemes=data.get("tantiemes"),
        )


@dataclass
class Referentiel:
    """Référentiel versionné porté par l'appel : familles (et leurs
    tantièmes) + règles de répartition par défaut (D-0016). L'appel en
    conserve sa copie à la construction ; le versionnement du dossier
    (dates de validité) relève du lot 4.
    """

    familles: list = field(default_factory=list)
    regles_par_defaut: dict = field(default_factory=lambda: dict(REGLES_DEFAUT))

    def __post_init__(self):
        self.familles = list(self.familles)
        self.regles_par_defaut = dict(self.regles_par_defaut)
        identifiants = [f.identifiant for f in self.familles]
        if len(identifiants) != len(set(identifiants)):
            raise ErreurValidation(
                "identifiants de lots en doublon dans le référentiel", "lot"
            )
        self._par_id = {f.identifiant: f for f in self.familles}

    def famille(self, identifiant: str) -> Famille:
        try:
            return self._par_id[identifiant]
        except KeyError:
            raise ErreurValidation(
                f"lot inconnu dans le référentiel : {identifiant!r}", "lot"
            ) from None

    def mode_defaut(self, type_charge: TypeCharge) -> ModeRepartition:
        try:
            return self.regles_par_defaut[type_charge]
        except KeyError:
            raise ErreurValidation(
                f"aucune règle par défaut pour le type {type_charge!r}", "regle"
            ) from None

    def lots_copro(self) -> list:
        return [f for f in self.familles if f.copropriete]

    def lots_hors_copro(self) -> list:
        return [f for f in self.familles if not f.copropriete]

    def to_dict(self) -> dict:
        return {
            "familles": [f.to_dict() for f in self.familles],
            "regles_par_defaut": {
                t.value: m.value for t, m in self.regles_par_defaut.items()
            },
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Referentiel":
        familles = [Famille.from_dict(f) for f in data.get("familles", [])]
        regles = {
            TypeCharge.de_libelle(t): ModeRepartition.de_libelle(m)
            for t, m in data.get("regles_par_defaut", {}).items()
        }
        return cls(familles=familles, regles_par_defaut=regles)


# ---------------------------------------------------------------------------
# Facture
# ---------------------------------------------------------------------------


@dataclass
class Facture:
    """Une facture de charge : montant en centimes, type, mode de
    répartition. ``mode`` explicite (dérogation éventuelle) ou None : la
    facture suit alors la règle par défaut de son type (D-0016).

    Le montant copropriété n'est jamais saisi : il est dérivé des parts
    (plan §4.3). La date est optionnelle : absente ou hors période, elle
    produit un avertissement (D-0025), l'exigence de date étant portée par
    l'UI au lot 5.
    """

    identifiant: str
    type_charge: TypeCharge
    montant_centimes: int
    mode: object = None
    fournisseur: str = ""
    detail: str = ""
    date_facture: date = None

    def __post_init__(self):
        if not self.identifiant or not isinstance(self.identifiant, str):
            raise ErreurValidation(
                f"identifiant de facture requis : {self.identifiant!r}", "facture"
            )
        if not isinstance(self.type_charge, TypeCharge):
            raise ErreurValidation(
                f"type de charge invalide : {self.type_charge!r}", "type_charge"
            )
        if not isinstance(self.montant_centimes, int) or self.montant_centimes <= 0:
            raise ErreurValidation(
                f"montant de facture invalide (centimes > 0 attendu) : "
                f"{self.montant_centimes!r}",
                "montant",
            )
        if self.mode is not None and not isinstance(self.mode, ModeRepartition):
            raise ErreurValidation(
                f"mode de répartition invalide : {self.mode!r}", "mode"
            )
        if self.date_facture is not None and not isinstance(self.date_facture, date):
            raise ErreurValidation(
                f"date de facture invalide : {self.date_facture!r}", "date"
            )

    def mode_effectif(self, referentiel: Referentiel) -> ModeRepartition:
        """Mode appliqué : explicite si dérogation, sinon règle par défaut."""
        if self.mode is not None:
            return self.mode
        return referentiel.mode_defaut(self.type_charge)

    def to_dict(self) -> dict:
        return {
            "identifiant": self.identifiant,
            "type_charge": self.type_charge.value,
            "montant_centimes": self.montant_centimes,
            "mode": self.mode.value if self.mode is not None else None,
            "fournisseur": self.fournisseur,
            "detail": self.detail,
            "date_facture": (
                self.date_facture.isoformat() if self.date_facture else None
            ),
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Facture":
        return cls(
            identifiant=data["identifiant"],
            type_charge=TypeCharge.de_libelle(data["type_charge"]),
            montant_centimes=int(data["montant_centimes"]),
            mode=(
                ModeRepartition.de_libelle(data["mode"])
                if data.get("mode")
                else None
            ),
            fournisseur=data.get("fournisseur", ""),
            detail=data.get("detail", ""),
            date_facture=(
                date.fromisoformat(data["date_facture"])
                if data.get("date_facture")
                else None
            ),
        )


# ---------------------------------------------------------------------------
# Relevés d'eau (D-0017)
# ---------------------------------------------------------------------------


@dataclass
class ReleveEau:
    """Relevé d'un compteur d'eau : index à trois décimales (m³), poids en
    litres. ``remplacement`` lève le contrôle « nouvel >= ancien » (changement
    de compteur, capacité documentée D-0017, jamais observé dans l'oracle).
    """

    lot: str
    compteur: str
    ancien_index: Decimal
    nouvel_index: Decimal
    remplacement: bool = False

    def __post_init__(self):
        if not self.lot or not isinstance(self.lot, str):
            raise ErreurValidation(
                f"lot de relevé requis : {self.lot!r}", "releve"
            )
        self.ancien_index = self._index(self.ancien_index, "ancien")
        self.nouvel_index = self._index(self.nouvel_index, "nouvel")
        if not self.remplacement and self.nouvel_index < self.ancien_index:
            raise ErreurValidation(
                f"nouvel index < ancien index pour le lot {self.lot} sans "
                "remplacement de compteur",
                "releve",
            )

    @staticmethod
    def _index(valeur, role: str) -> Decimal:
        try:
            d = valeur if isinstance(valeur, Decimal) else Decimal(str(valeur))
        except Exception as exc:
            raise ErreurValidation(
                f"index {role} illisible : {valeur!r}", "releve"
            ) from exc
        if not d.is_finite():  # B-14 : nan/inf deviennent erreur de
            raise ErreurValidation(  # validation, jamais exception brute
                f"index {role} non fini : {valeur!r}", "releve"
            )
        if d < 0:
            raise ErreurValidation(
                f"index {role} négatif : {valeur!r}", "releve"
            )
        try:
            quantifie = d.quantize(Decimal("0.001"))
        except (ArithmeticError, ValueError) as exc:
            # B-14 : un index démesuré (26+ chiffres) devient une erreur
            # de validation, jamais une exception brute.
            raise ErreurValidation(
                f"index {role} démesuré : {valeur!r}", "releve"
            ) from exc
        if d != quantifie:
            raise ErreurValidation(
                f"index {role} avec plus de trois décimales : {valeur!r}",
                "releve",
            )
        return quantifie

    @property
    def consommation_m3(self) -> Decimal:
        return (self.nouvel_index - self.ancien_index).quantize(Decimal("0.001"))

    @property
    def consommation_litres(self) -> int:
        """Poids exact du lot pour la répartition au plus fort reste."""
        return int(self.consommation_m3 * 1000)

    def to_dict(self) -> dict:
        return {
            "lot": self.lot,
            "compteur": self.compteur,
            "ancien_index": str(self.ancien_index),
            "nouvel_index": str(self.nouvel_index),
            "remplacement": self.remplacement,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "ReleveEau":
        return cls(
            lot=data["lot"],
            compteur=data.get("compteur", ""),
            ancien_index=Decimal(data["ancien_index"]),
            nouvel_index=Decimal(data["nouvel_index"]),
            remplacement=bool(data.get("remplacement", False)),
        )


